"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq

Cell = tuple[int, int]  # (row, col)

_ENTER_COST: dict[str, int] = {".": 1, "D": 3, "S": 1, "G": 1}


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    start: Cell | None = None
    goal: Cell | None = None
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == "S" and start is None:
                start = (r, c)
            elif ch == "G" and goal is None:
                goal = (r, c)
    if start is None or goal is None:
        return None

    best: dict[Cell, int] = {start: 0}
    prev: dict[Cell, Cell] = {}
    heap: list[tuple[int, Cell]] = [(0, start)]
    while heap:
        dist, cur = heapq.heappop(heap)
        if dist > best.get(cur, dist):
            continue
        if cur == goal:
            path = [cur]
            while path[-1] in prev:
                path.append(prev[path[-1]])
            return path[::-1]
        r, c = cur
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if nr < 0 or nr >= len(grid) or nc < 0 or nc >= len(grid[nr]):
                continue
            cost = _ENTER_COST.get(grid[nr][nc])
            if cost is None:
                continue
            nd = dist + cost
            if nd < best.get((nr, nc), nd + 1):
                best[(nr, nc)] = nd
                prev[(nr, nc)] = cur
                heapq.heappush(heap, (nd, (nr, nc)))
    return None

